import{z as s,x as i,o as A,c as d,q as r,j as l,D as e,d as a,s as t,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"侧信道","description":"","frontmatter":{"title":"侧信道","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ce-side-channels.md","filePath":"cs/ce-side-channels.md","lastUpdated":1791413859000}'),c={name:"cs/ce-side-channels.md"};function F(h,E,D,p,C,m){const n=i("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="侧信道" tabindex="-1">侧信道 <a class="header-anchor" href="#侧信道" aria-label="Permalink to &quot;侧信道&quot;">​</a></h1><div class="epigraph"><p>密钥可以在数学上无懈可击，同时从功耗曲线、缓存命中或一条分支里整字节整字节地漏出去——实现本身就是一条明文通道。</p><footer>—— 据 Kocher, 1996；Kocher, Jaffe and Jun, 1999；Bernstein, 2005 整理</footer></div><p><a href="/cs/ce-protocol-pitfalls">上一课</a>把组合层的预言机钉在错误码与时序上。时序往下挖一层就是本课：不只协议的分支在漏，一次乘法、一次查表、一个依赖密钥的内存地址，都在把秘密写进可测物理量。Kocher 1996 用纯计时差解出 RSA 的指数位；Kocher, Jaffe and Jun 1999 的差分功耗分析（DPA）在智能卡上批量恢复密钥；Bernstein 2005 证明缓存时序可以隔着网络打 AES。缺口是把「实现不能泄露」变成可检查的工程标准：什么操作在什么模型下算漏，常量时间到底约束哪几类指令。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>秘密进入计算后，沿三条物理通道外出。其一，时间：分支与提前返回让执行时长依赖密钥位，查表让访存地址依赖密钥位。其二，功耗与电磁：电路翻转次数与处理的数据相关，同一密钥上千次采样的功耗曲线做差分，相关峰直接标出密钥字节。其三，共享资源：同一 CPU 上的另一个进程（或另一台虚机）可通过缓存组的命中状态观察受害者的访存模式，Flush+Reload（Yarom and Falkner 2013）把测量精度做到一条 cache line。数学安全证明对这些通道全部失明：归约里的攻击者拿不到计时器。缺口是定一条可实现的安全线，而不是要求「实现无物理泄露」。<span class="marginnote">「侧信道」可以类比成保险箱：密码锁的数学再精密，贴着墙听转轮的咔嗒声也能把组合猜出来——攻击者不走「正门」（破解算法），而听实现发出的「声音」（时间、功耗、缓存）。所以「算法有安全证明」与「实现会漏」并不矛盾：证明的游戏里压根没有计时器这个道具。</span></p><h3 id="常量时间的可检查定义" tabindex="-1">常量时间的可检查定义 <a class="header-anchor" href="#常量时间的可检查定义" aria-label="Permalink to &quot;常量时间的可检查定义&quot;">​</a></h3><p>工程上「常量时间」有可操作的判据，只有三条禁令：秘密不得进入分支条件；秘密不得进入内存地址（数组下标）；与秘密相关的执行时间不得依赖其值（除法、提前退出、可变循环次数都算）。满足三条，执行流与访存序列对秘密独立，时间与缓存两个通道即关闭。<span class="marginnote">把三条禁令翻译成代码形状：禁令一是 <code>if (key_bit)</code> 这种分支——真走假走时间不同；禁令二是 <code>table[key &amp; 0xff]</code> 这种下标——那一条 cache line 命中与否，等于把 key 的低 8 位广播出去；禁令三是 <code>while (t &gt; 0)</code> 里 t 与秘密相关——循环次数就是倒计时。三条都避开，秘密才进不了可观测序列。</span>功耗通道要靠掩蔽与双轨逻辑，属于硬件层，本课只划界不展开。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>落地做法按算法族分。模幂（RSA）：固定窗口数、预计算全表、Montgomery 乘法常量时间，另加指数盲化 \\(d&#39; = d + r\\cdot\\varphi(n)\\)——即使有残余时序差，也不与真实指数对齐。标量乘（ECC）：Montgomery 阶梯天然每步对称，X25519 在 RFC 7748 里把「阶梯加常量时间」写进规范本身，这是「合同进接口」的范例。AES：软件实现弃查表改用 bitsliced 或 AES-NI 硬件指令，密钥装进独立电路后缓存通道消失。比较（MAC 标签）：逐字节异或累积、最后统一判断——<a href="/cs/ce-protocol-pitfalls">协议实现的陷阱</a>里「常量时间比较」的机器级实现。最后一条纪律管编译器：优化器有权把「秘密控制的选择」改回分支、把查表展开，常量时间必须在编译产物上复核，源码级审查不够。</p>',9)),(A(),l(o,null,{default:e(()=>[t(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SECRET%5B%22%E7%A7%98%E5%AF%86%20k%20%E8%BF%9B%E5%85%A5%E8%BF%90%E7%AE%97%22%5D%20--%3E%20CH%7B%22%E5%8F%AF%E8%A7%82%E6%B5%8B%E9%80%9A%E9%81%93%22%7D%0A%20%20CH%20--%3E%20T%5B%22%E6%97%B6%E9%97%B4%EF%BC%9A%E5%88%86%E6%94%AF%20%2F%20%E6%8F%90%E5%89%8D%E8%BF%94%E5%9B%9E%22%5D%0A%20%20CH%20--%3E%20M%5B%22%E8%AE%BF%E5%AD%98%E5%9C%B0%E5%9D%80%EF%BC%9A%E6%9F%A5%E8%A1%A8%E7%B4%A2%E5%BC%95%E5%90%AB%E5%AF%86%E9%92%A5%E4%BD%8D%22%5D%0A%20%20CH%20--%3E%20P%5B%22%E5%8A%9F%E8%80%97%20%2F%20%E7%94%B5%E7%A3%81%EF%BC%9A%E7%BF%BB%E8%BD%AC%E6%AC%A1%E6%95%B0%E7%9B%B8%E5%85%B3%22%5D%0A%20%20T%20--%3E%20LEAK%5B%22%E5%B7%AE%E5%88%86%E5%88%86%E6%9E%90%E6%81%A2%E5%A4%8D%E5%AF%86%E9%92%A5%22%5D%0A%20%20M%20--%3E%20LEAK%0A%20%20P%20--%3E%20DPA%5B%22DPA%EF%BC%9A%E5%8D%83%E6%AC%A1%E9%87%87%E6%A0%B7%E6%B1%82%E7%9B%B8%E5%85%B3%E5%B3%B0%22%5D%0A%20%20FIX%5B%22%E4%B8%89%E6%9D%A1%E7%A6%81%E4%BB%A4%20%2B%20%E7%9B%B2%E5%8C%96%20%2F%20%E9%98%B6%E6%A2%AF%20%2F%20%E7%A1%AC%E4%BB%B6%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20SAFE%5B%22%E6%97%B6%E5%BA%8F%E4%B8%8E%E7%BC%93%E5%AD%98%E9%80%9A%E9%81%93%E5%85%B3%E9%97%AD%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("侧信道攻击的共同机制是"),B("strong",null,"把秘密变成可分的信号"),a("：一次测量里泄露混在噪声里，多次测量按猜测分组求平均（DPA）或按地址对齐（Flush+Reload），信号从噪声里立起来。防御因此分两层：降低单次泄露（常量时间让信号源头为零），提高对齐成本（盲化让每次测量的目标不同）。Brumley and Boneh 2003 证明这仗隔着网络也能打：OpenSSL 的 RSA 时序差跨广域网仍可统计出指数位。反过来，这条机制也解释了为什么「常量时间」是可实现的标准：它不要求消除物理世界的全部相关性，只要求秘密与可观测序列在指令层面独立——这是编译器选项与检测工具（ctgrind 一类）能机械检查的性质。")],-1)),(A(),l(o,null,{default:e(()=>[t(n,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20M1%5B%22%E6%B5%8B%E9%87%8F%201%EF%BC%9A%E6%9B%B2%E7%BA%BF%20%3D%20%E4%BF%A1%E5%8F%B7%20%2B%20%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20AVG%5B%22%E6%8C%89%E7%8C%9C%E6%B5%8B%E5%88%86%E7%BB%84%EF%BC%8C%E5%AF%B9%E9%BD%90%E6%B1%82%E5%B9%B3%E5%9D%87%22%5D%0A%20%20M2%5B%22%E6%B5%8B%E9%87%8F%20N%EF%BC%9A%E7%9B%AE%E6%A0%87%E5%9B%BA%E5%AE%9A%E5%88%99%E4%BF%A1%E5%8F%B7%E5%90%8C%E5%90%91%22%5D%20--%3E%20AVG%0A%20%20AVG%20--%3E%20PEAK%5B%22%E5%99%AA%E5%A3%B0%E4%BA%92%E6%B6%88%EF%BC%8C%E4%BF%A1%E5%8F%B7%E7%AB%8B%E8%B5%B7%EF%BC%9A%E5%B3%B0%E6%A0%87%E5%87%BA%E5%AF%86%E9%92%A5%E5%AD%97%E8%8A%82%22%5D%0A%20%20PEAK%20--%3E%20BLIND%5B%22%E7%9B%B2%E5%8C%96%EF%BC%9A%E6%AF%8F%E6%AC%A1%E6%B5%8B%E9%87%8F%E7%9A%84%E7%9B%AE%E6%A0%87%E8%A2%AB%E9%9A%8F%E6%9C%BA%E6%8C%AA%E4%BD%8D%22%5D%0A%20%20BLIND%20--%3E%20SPREAD%5B%22%E4%BF%A1%E5%8F%B7%E4%B8%8D%E5%86%8D%E5%90%8C%E5%90%91%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20SPREAD%20--%3E%20SAFE%5B%22%E5%B9%B3%E5%9D%87%E5%8D%83%E6%AC%A1%E4%B9%9F%E6%8D%9E%E4%B8%8D%E5%87%BA%E5%B3%B0%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">盲化的直觉：像谈判时先在心里把真实底价加一个随机数再表露，测到的「报价」每次都不同——单次测量对不准真实值，反复平均也对不齐。RSA 的 \\(d&#39; = d + r\\cdot\\varphi(n)\\) 是同一个想法的代数版：余数运算保证 \\(d&#39;\\) 与 \\(d\\) 算出的结果完全一致，但时序攻击量到的是每次都换了模样的 \\(d&#39;\\)。</span></p><p><span class="marginnote">查表的账：一张 256 字节的 S 盒占 4 条 64 字节 cache line，查表索引含 8 位密钥；cache 命中约几纳秒、未命中约百纳秒，差两个数量级——Bernstein 2005 的远程 AES 攻击与 Flush+Reload 攻击吃的是同一个信号。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>功耗与电磁通道、掩蔽与双轨逻辑属于硬件安全，本课只点名不展开；容错攻击（Rowhammer、电压毛刺改写计算）也在界外。本课的「常量时间」针对时序与缓存两个通道，不承诺对抗持有近场测量装备的攻击者。协议层失败（错误码预言机）已由上一课收口；随机数侧的失败——熵不足与时序可预测的非密码 RNG——留给「随机数」课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>秘密沿时间、功耗、共享缓存三条通道外泄；数学归约对它们失明。</li><li>常量时间三条禁令：无秘密分支、无秘密下标、无秘密相关的执行时间。</li><li>防御两层：常量时间消信号源，盲化与阶梯提高对齐成本；X25519 把阶梯写进规范。</li><li>常量时间要在编译产物上复核；功耗通道由硬件层另解。</li><li>出处：Kocher, 1996；Kocher, Jaffe and Jun, 1999；Bernstein, 2005；Yarom and Falkner, 2013；RFC 7748。</li></ul>',6))])}const S=s(c,[["render",F]]);export{u as __pageData,S as default};
